'use strict';
// Browser-only records. Production owns persistence, worker scheduling and receipt verification.
const trialRecords=new Map(), paymentRecords=new Map();
function recordKey(r){return r.id||(r.name==='Netflix'?'netflix-primary':r.name.toLowerCase());}
function plusDays(date,days){if(!/^\d{4}-\d{2}-\d{2}$/.test(date||''))return '';const d=new Date(date+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+Number(days));return Number.isFinite(d.getTime())?d.toISOString().slice(0,10):'';}
function nextCycle(anchor,cycle,index=1){if(cycle==='Weekly')return plusDays(anchor,7*index);const d=new Date(anchor+'T00:00:00Z'),month=d.getUTCMonth()+({Monthly:1,Quarterly:3,Yearly:12}[cycle]||1)*index,year=d.getUTCFullYear(),day=d.getUTCDate();return new Date(Date.UTC(year,month,Math.min(day,new Date(Date.UTC(year,month+1,0)).getUTCDate()))).toISOString().slice(0,10);}
function trialEnd(r){return r.trialEndSource==='exact'&&r.trialEnd?r.trialEnd:Number(r.trialDays)>0?plusDays(r.start,r.trialDays):'';}
function trackedRecord(raw){const r={currency:'USD',cycle:'Monthly',...raw},end=trialEnd(r);r.id=recordKey(r);r.trialEnd=end;r.trial=!!end&&end>=calendarToday&&!['Cancelled','Expired'].includes(r.status);r.trialEnded=!!end&&end<calendarToday&&r.autoRenew===false;if(end){r.renewal=end;if(end<calendarToday&&r.autoRenew!==false){let i=1;while(nextCycle(end,r.cycle,i)<calendarToday&&i<2400)i++;r.renewal=nextCycle(end,r.cycle,i);}if(r.trialEnded)r.renewal='';}return r;}
function allTrackedRecords(){const base=[...listSamples,...relatedPreviewRecords.slice(1),{id:'duolingo-calendar',name:'Duolingo',price:'9.99',currency:'USD',cycle:'Monthly',category:'Education',renewal:'2026-10-29',source:'AI'}];const map=new Map(base.map(r=>[recordKey(r),r.name==='Spotify'?{...r,source:'Gmail',inboxEmail:'alex@example.com',start:'2026-10-24',trialDays:7,trialDuration:'7 days',trialEnd:'2026-10-31',trialEndSource:'exact',autoRenew:true,confidence:'review-required'}:r]));for(const [id,r]of trialRecords)map.set(id,r);return [...map.values()].filter(r=>r.status!=='Deleted').map(trackedRecord);}
function trialFields(){return `<div class="trial-fields">${selectField({label:'Trial days · Optional',name:'trialDuration',options:['No trial','3 days','7 days','14 days','30 days','Custom']})}<label data-custom-trial hidden>Custom trial days<input name="trialDaysCustom" type="number" min="1" max="365" step="1" placeholder="e.g. 21"><span class="manual-error" aria-live="polite" hidden></span></label></div>`;}
function trialFormSummary(){return `<div class="trial-fields trial-form-summary" data-trial-settings hidden><p class="trial-calculation" aria-live="polite"></p><label class="trial-switch"><span>Renews automatically after trial</span><input type="checkbox" name="autoRenew" role="switch" checked></label><p class="note" data-trial-tracking-hint>Tracks future renewals in Renewless. It doesn’t change your settings on the service or confirm payment.</p></div>`;}
function initTrialForm(form,record){if(record){form.dataset.originalTrial=JSON.stringify({start:record.start,days:Number(record.trialDays),end:record.trialEnd,source:record.trialEndSource});form.elements.trialDuration.value=record.trialDuration||(record.trialDays?([3,7,14,30].includes(Number(record.trialDays))?record.trialDays+' days':'Custom'):'No trial');form.elements.trialDaysCustom.value=record.trialDays||'';form.elements.autoRenew.checked=record.autoRenew!==false;}syncTrialForm(form);}
function formTrialDays(form){const v=form.elements.trialDuration.value;return v==='No trial'?0:v==='Custom'?Number(form.elements.trialDaysCustom.value):parseInt(v,10);}
function syncTrialForm(form){const enabled=form.elements.trialDuration.value!=='No trial',days=formTrialDays(form),start=form.elements.start,renewal=form.elements.renewal;
 if(enabled&&form.dataset.trialEnabled!=='true')form.dataset.nonTrialRenewal=renewal.value;
 if(!enabled&&form.dataset.trialEnabled==='true')renewal.value=form.dataset.nonTrialRenewal||'';
 form.dataset.trialEnabled=String(enabled);
 form.querySelector('[data-custom-trial]').hidden=form.elements.trialDuration.value!=='Custom';form.elements.trialDaysCustom.required=form.elements.trialDuration.value==='Custom';form.querySelector('[data-trial-settings]').hidden=!enabled;start.required=enabled;start.closest('label').querySelector('small').textContent=enabled?'Required for trial':'Optional';renewal.required=!enabled;renewal.closest('label').hidden=enabled;form.elements.price.closest('label').firstChild.textContent=enabled?'Price after trial':'Amount';
 const original=JSON.parse(form.dataset.originalTrial||'{}'),end=original.source==='exact'&&original.start===start.value&&original.days===days?original.end:start.value&&Number.isInteger(days)&&days>0&&days<=365?plusDays(start.value,days):'';
 const summary=form.querySelector('.trial-calculation');summary.textContent=end?'Trial ends · '+detailDate(end):!start.value?'Choose a start date to calculate the trial end.':'Enter valid trial days to calculate the trial end.';summary.classList.toggle('is-calculated',!!end);
 if(enabled)renewal.value=end;
 form.querySelector('[data-trial-tracking-hint]').textContent=(form.elements.autoRenew.checked?'Tracks future renewals in Renewless.':'Tracks the trial end only. No renewals are projected.')+' It doesn’t change your settings on the service or confirm payment.';
 for(const field of [start,form.elements.trialDaysCustom]){if(!field.required||field.getAttribute('aria-invalid')==='true'&&field.value&&field.validity.valid){field.setAttribute('aria-invalid','false');field.nextElementSibling.hidden=true;field.nextElementSibling.textContent='';}}
}
function validateTrialForm(form){syncTrialForm(form);let valid=true;for(const field of [form.elements.start,form.elements.trialDaysCustom]){let message='';if(field.required&&!field.value)message=field.name==='start'?'Select a start date to calculate your trial end date.':'Enter your trial duration.';else if(field.name==='trialDaysCustom'&&field.required&&(!Number.isInteger(Number(field.value))||Number(field.value)<1||Number(field.value)>365))message='Enter a whole number from 1 to 365.';field.setAttribute('aria-invalid',String(!!message));field.nextElementSibling.textContent=message;field.nextElementSibling.hidden=!message;if(message)valid=false;}return valid;}
function storeTrialForm(form){const r=state.manual;r.id=form.dataset.edit==='true'?recordKey(r):'manual-'+Date.now();r.trialDays=formTrialDays(form);r.autoRenew=form.elements.autoRenew.checked;const original=JSON.parse(form.dataset.originalTrial||'{}');r.trialEndSource=original.source==='exact'&&original.start===r.start&&original.days===r.trialDays?'exact':'calculated';r.trialEnd=r.trialEndSource==='exact'?original.end:r.trialDays?plusDays(r.start,r.trialDays):'';r.confidence=r.confidence||'user-entered';trialRecords.set(r.id,{...r});reminderPreferences.delete(r.id);state.manual=trackedRecord(r);}
function trialDetail(r){return r.trialEnd?`<section class="panel"><h3>Trial tracking</h3>${r.trialEnded?fr('Trial ended',detailDate(r.trialEnd)):''}${fr('Auto-renew tracking',r.autoRenew===false?'Off':'On')}<p class="note">${r.trialEnded?'Trial ended. No recurring charges are projected.':'Renewal tracking does not confirm payment or change your service settings.'}</p></section>`:'';}
function paymentCycle(r){if(!r.trialEnd)return r.renewal||calendarToday;if(r.trialEnd>=calendarToday)return r.trialEnd;let i=0;while(nextCycle(r.trialEnd,r.cycle,i+1)<=calendarToday&&i<2400)i++;return i?nextCycle(r.trialEnd,r.cycle,i):r.trialEnd;}
document.addEventListener('change',e=>{const form=e.target.closest('.manual-form');if(form&&['trialDuration','trialDaysCustom','start','autoRenew'].includes(e.target.name))syncTrialForm(form);});
document.addEventListener('input',e=>{const form=e.target.closest('.manual-form');if(form&&['trialDaysCustom','start'].includes(e.target.name))syncTrialForm(form);});
function trialSpendingSummary(){const trials=spendingRecords().filter(r=>r.trial);return trials.length?`<div class="trial-spending"><h3>Free trials · ${trials.length}</h3><p class="note">Not included in current monthly spend.</p>${trials.map(r=>`<button class="calendar-event" data-spend-record="${escape(r.id)}"><span class="avatar">${platformLogo(r.name)}</span><span class="calendar-event-name"><strong>${escape(r.name)}</strong><small>Trial ends ${detailDate(r.trialEnd)}</small><small>Then ${escape(r.currency)} ${Number(r.price).toFixed(2)} · ${escape(r.cycle)}</small></span><span>›</span></button>`).join('')}</div>`:'';}
function nearestEvents(){const [year,month]=calendarToday.split('-').map(Number);return [0,1,2].flatMap(i=>{const d=new Date(Date.UTC(year,month-1+i,1));return calendarEvents({year:d.getUTCFullYear(),month:d.getUTCMonth()});}).filter(r=>r.renewal>=calendarToday);}
function homeNextEvent(quiet){const next=nearestEvents()[0];if(quiet||!next)return '<section class="home-renewal"><p class="eyebrow">UPCOMING</p><p class="note">No renewals or trials ending in the next 7 days.</p></section>';return `<section class="home-renewal"><div class="home-renewal-label"><span class="eyebrow">${next.trial?'TRIAL ENDING':'NEXT RENEWAL'}</span><small>${detailDate(next.renewal)}</small></div>${spendRecordRow(next)}</section>`;}
function trialReviewCard(r){return `<section class="panel"><span class="detail-status status-trial">Free trial</span><h3>${escape(r.name)}</h3><p>Trial ends ${detailDate(trialEnd(r))}</p><p class="note">${escape(r.currency)} ${Number(r.price).toFixed(2)} · ${escape(r.cycle)} after trial</p><p class="note">${r.trialEndSource==='exact'?'Exact end date found in source':'Calculated from start date and duration'}. Review before saving.</p><button class="primary" data-review-trial data-trial-source="${current==='AI chat · trial'?'AI':'Gmail'}">${current==='AI chat · trial'?'Create subscription':'Review details'}</button></section>`;}
function trialReviewScreen(source='Gmail'){return heading('Review trial',true)+trialReviewCard({name:'Spotify',price:'11.99',currency:'USD',cycle:'Monthly',start:'2026-10-24',trialDays:7,trialEnd:'2026-10-31',trialEndSource:'exact'})+'<p class="note">Check the trial date, price after trial and auto-renew tracking before saving.</p>';}
function trialAlertScreen(){return heading('Alerts')+'<p class="note">Only reminders that have already been sent.</p><div class="rows"><button class="row" data-go="Detail · trial"><span class="avatar">'+platformLogo('Spotify')+'</span><span class="body"><strong>Spotify</strong><small>Your trial ends on 31 Oct</small><small>24 Oct · 9:00 · Sent</small></span><span class="status-trial">Trial ending</span></button></div>';}
document.addEventListener('click',e=>{if(e.target.closest('[data-review-trial]')){state.manual={id:'spotify',name:'Spotify',price:'11.99',currency:'USD',cycle:'Monthly',source:e.target.closest('[data-review-trial]').dataset.trialSource,inboxEmail:'alex@example.com',start:'2026-10-24',trialDays:7,trialDuration:'7 days',trialEnd:'2026-10-31',trialEndSource:'exact',autoRenew:true};demoName='Spotify';demoPrice='11.99';if(e.target.closest('[data-review-trial]').dataset.trialSource==='AI'){trialRecords.set('spotify',{...state.manual});go('Detail');toast('Subscription added.');}else go('Edit');}});

function confirmedPaymentSummary(){const totals={};for(const r of paymentRecords.values())totals[r.currency]=(totals[r.currency]||0)+Math.round(r.amount*100);return panel('<span class="metric-label">Confirmed payments</span><h3>'+ (Object.entries(totals).map(([currency,cents])=>escape(currency)+' '+(cents/100).toFixed(2)).join(' · ')||'No payments confirmed')+'</h3>'+btn('View payments','Payments','link'));}

function trialFormAfterRender(){if(!['Add form','Edit'].includes(current))return;document.querySelector('[data-variant=upgraded] .variant-title small').textContent='Final design · locked';document.getElementById('context').textContent='Final Add/Edit · Approved form and trial days, required start date, calculated end and tracking switch. Local form/save preview; native/API integration is separate.';}
